    event.preventDefault();if(busy||accessLost)return;setError(null);setLatest(null);setBusy(true);
    try {
      const payload=issuePayload(form);
      const body=baseline?{...changedFields(issuePayload(issueForm(baseline)),payload),expectedRevision:baseline.revision}:payload;
      if(baseline&&Object.keys(body).length===1){onCancel();return;}
      await onSave(body);
